o_gloom_newknot_title:"结愿的人",echo_gloom_newknot_desc:"麻布条末端总有人再添一结——这棵树从未许过愿，可系布的队伍每年都排得更长。",echo_radiant_mirrorpool_title:"门前镜潭",echo_radiant_mirrorpool_desc:"绯红门影倒映在脚下镜潭——穿过的人从不回头看自己的影子，因为影子里那副铠甲等了他很久了。",echo_radiant_bannermender_title:"补旗人",echo_radiant_bannermender_desc:"每年立春都有个老人来补旗脚——他从不动金线，他说：会放手的那部分，本来就属于天空。",echo_radiant_bellfounder_title:"铸铃匠",echo_radiant_bellfounder_desc:"圣殿深处有一间藤蔓丛生的铸造坊——最后一口吊钟不是铸出来的，是从上一任主教的牙齿里剥出来的。",ach_echo_gloom_six_title:"薄暮六响",ach_echo_gloom_six_desc:"薄暮回响全六枚齐鸣",ach_echo_radiant_six_title:"辉煌六耀",ach_echo_radiant_six_desc:"辉煌残响全六枚齐鸣",common_cancel:"取消",common_close:"关闭",common_save:"保存",common_ui:"界面",settings_title:"设置",settings_language:"语言",settings_difficulty:"难度",settings_accessibility:"辅助功能",settings_colorvision:"色觉模式",settings_captions:"字幕（音频线索可视化）",settings_caption_size:"字幕大小",settings_caption_small:"小",settings_caption_medium:"中",settings_caption_large:"大",settings_ui_text:"界面文字",settings_ui_text_small:"小",settings_ui_text_medium:"标准",settings_ui_text_large:"大",caption_gear_drop:"掉落：${rarity}",caption_pickup:"已拾取",caption_execution:"处决",settings_look_sensitivity:"镜头灵敏度",settings_brightness:"画面亮度",settings_shake:"震屏强度",settings_shake_full:"全开",settings_shake_reduced:"减弱",settings_shake_off:"关闭",settings_flash:"闪光强度",settings_flash_full:"全开",settings_flash_reduced:"减弱",settings_flash_off:"无闪光",settings_graphics:"画面",settings_master_volume:"主音量",settings_sfx_volume:"音效音量",settings_music_volume:"音乐音量",settings_ambient_volume:"环境音量",settings_pixel_ratio:"渲染精度",settings_lod_distance:"敌人更新距离",settings_shadows:"阴影",settings_shadow_quality:"阴影精度",settings_msaa:"抗锯齿",settings_msaa_off:"关",settings_ssao:"环境光遮蔽",settings_graphics_preset:"画质预设",settings_vibration:"手柄震动",settings_online:"在线服务",settings_online_toggle:"启用在线服务（排行榜 / 遥测）",settings_online_hint:"默认关闭。开启后击杀 Boss 会向网关上报遥测；关掉网络也不会影响本地游戏。",settings_online_lb_btn:"刷新排行榜",settings_online_lb_unavailable:"拉不到排行榜：在线服务未开启或网关连不上",settings_online_lb_empty:"排行榜还是空的",settings_online_presen